 if($("#auditTable"))$("#auditTable").innerHTML=state.audit.map(x=>`<tr><td>${esc(x.at)}</td><td>${esc(x.action)}</td><td>${esc(x.object)}</td></tr>`).join("");
 if($("#ordersList"))$("#ordersList").innerHTML=state.orders.map((x,i)=>`<div class="row"><div><strong>${esc(x.text)}</strong><span>${esc(x.owner)} · ${esc(x.status)}</span></div><button data-order-done="${i}">Исполнить</button></div>`).join("")||"<p>Поручений нет</p>";
